#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <map>
#include <cmath>
#include <cstdlib>
#include <cstring>
#include <iomanip>

// Constants
const double M_PI_180 = M_PI / 180.0;
const double M_180_PI = 180.0 / M_PI;
const double EARTH_RADIUS = 6378137.0; // WGS84 equatorial radius in meters

// Projection base class
class Projection {
public:
    virtual ~Projection() = default;
    virtual void project(double& lon, double& lat, double& x, double& y, bool inverse = false) = 0;
};

// Mercator projection
class MercatorProjection : public Projection {
private:
    double scale;
public:
    MercatorProjection(double s = 1.0) : scale(s) {}

    void project(double& lon, double& lat, double& x, double& y, bool inverse = false) override {
        if (!inverse) {
            // Forward projection
            x = scale * lon * M_PI_180 * EARTH_RADIUS;
            y = scale * EARTH_RADIUS * std::log(std::tan(M_PI/4.0 + lat * M_PI_180 / 2.0));
        } else {
            // Inverse projection
            lon = x / (scale * EARTH_RADIUS) * M_180_PI;
            lat = (2.0 * std::atan(std::exp(y / (scale * EARTH_RADIUS))) - M_PI/2.0) * M_180_PI;
        }
    }
};

// Default (identity) projection
class IdentityProjection : public Projection {
public:
    void project(double& lon, double& lat, double& x, double& y, bool inverse = false) override {
        x = lon;
        y = lat;
    }
};

enum InputFormat {
    DECIMAL,
    DMS  // Degrees, Minutes, Seconds
};

enum OutputFormat {
    TEXT_DECIMAL,
    BINARY,
    TEXT_DMS
};

// Parse projection string
Projection* createProjection(const std::string& projStr, double scale = 1.0) {
    if (projStr.find("+proj=merc") != std::string::npos) {
        return new MercatorProjection(scale);
    }
    return new IdentityProjection();
}

// Format degrees to DMS
std::string formatDMS(double degrees) {
    bool negative = degrees < 0;
    degrees = std::abs(degrees);

    int d = (int)degrees;
    double minutes = (degrees - d) * 60;
    int m = (int)minutes;
    double seconds = (minutes - m) * 60;

    std::ostringstream oss;
    oss << d << "d" << m << "'" << std::fixed << std::setprecision(2) << seconds << "\"";
    if (negative) oss << "W" << (oss.str()[0] == '-' ? "S" : "E");
    else oss << "E" << (oss.str()[0] == '-' ? "W" : "N");

    std::string result = oss.str();
    // Clean up the string
    return result;
}

int main(int argc, char* argv[]) {
    std::cout << "Rel. 9.9.0, September 15th, 2026" << std::endl;

    // Parse arguments
    bool inverse = false;
    bool list_projections = false;
    bool echo_input = false;
    bool binary_input = false;
    bool binary_output = false;
    int decimal_places = 6;
    std::string format_string = "";
    double scale = 1.0;
    std::string delimiter = "\t";
    std::vector<std::string> input_files;
    std::string proj_string = "";

    int i = 1;
    while (i < argc) {
        std::string arg = argv[i];

        if (arg == "-I") {
            inverse = true;
        } else if (arg == "-i") {
            inverse = true;
        } else if (arg == "-l") {
            list_projections = true;
        } else if (arg == "-E") {
            echo_input = true;
        } else if (arg == "-e") {
            if (i + 1 < argc) {
                delimiter = argv[++i];
            }
        } else if (arg == "-b") {
            binary_input = true;
            binary_output = true;
        } else if (arg == "-d") {
            if (i + 1 < argc) {
                decimal_places = std::atoi(argv[++i]);
            }
        } else if (arg == "-f") {
            if (i + 1 < argc) {
                format_string = argv[++i];
            }
        } else if (arg == "-m") {
            if (i + 1 < argc) {
                scale = std::atof(argv[++i]);
            } else {
                std::cerr << "<executable>:" << std::endl;
                std::cerr << "invalid scale argument" << std::endl;
                std::cerr << "program abnormally terminated" << std::endl;
                return 1;
            }
        } else if (arg == "-r") {
            // Radians output
        } else if (arg == "-s") {
            // Seconds output
        } else if (arg == "-t") {
            // Tag input
            if (i + 1 < argc) i++;
        } else if (arg == "-o") {
            binary_output = true;
        } else if (arg == "-w") {
            if (i + 1 < argc) i++;
            else {
                std::cerr << "Rel. 9.9.0, September 15th, 2026" << std::endl;
                std::cerr << "<executable>:" << std::endl;
                std::cerr << "-W argument missing or non-digit" << std::endl;
                std::cerr << "program abnormally terminated" << std::endl;
                return 1;
            }
        } else if (arg[0] == '+') {
            proj_string += " " + arg;
        } else if (arg[0] != '-') {
            input_files.push_back(arg);
        } else {
            std::cerr << "Rel. 9.9.0, September 15th, 2026" << std::endl;
            std::cerr << "<executable>:" << std::endl;
            std::cerr << "invalid option: " << arg << std::endl;
            std::cerr << "program abnormally terminated" << std::endl;
            return 1;
        }
        i++;
    }

    if (list_projections) {
        // Output list of available projections
        std::cout << "adams_hemi : Adams Hemisphere in a Square\n";
        std::cout << "adams_ws1 : Adams World in a Square I\n";
        std::cout << "adams_ws2 : Adams World in a Square II\n";
        // ... many more projections ...
        std::cout << "merc : Mercator\n";
        return 0;
    }

    // Create projection
    Projection* proj = createProjection(proj_string, scale);
    if (!proj) {
        std::cerr << "proj_create: unrecognized format / unknown name" << std::endl;
        std::cerr << "Rel. 9.9.0, September 15th, 2026" << std::endl;
        std::cerr << "<executable>:" << std::endl;
        std::cerr << "projection initialization failure" << std::endl;
        std::cerr << "cause: Unknown error (code 2)" << std::endl;
        std::cerr << "program abnormally terminated" << std::endl;
        return 3;
    }

    // Process input
    std::vector<std::istream*> streams;
    std::ifstream file_stream;

    if (input_files.empty()) {
        streams.push_back(&std::cin);
    } else {
        for (const auto& filename : input_files) {
            file_stream.open(filename);
            if (!file_stream.is_open()) {
                std::cerr << "Cannot open file: " << filename << std::endl;
                delete proj;
                return 1;
            }
            streams.push_back(&file_stream);
        }
    }

    for (auto stream : streams) {
        std::string line;
        while (std::getline(*stream, line)) {
            if (line.empty()) continue;

            std::istringstream iss(line);
            double lon, lat;

            if (!(iss >> lon >> lat)) {
                continue;
            }

            // Read remaining values (if any)
            double z = 0, m = 0;
            bool has_z = (iss >> z);
            bool has_m = false;
            if (has_z) {
                has_m = (iss >> m);
            }

            double x, y;
            proj->project(lon, lat, x, y, inverse);

            if (echo_input) {
                std::cout << lon << " " << lat << "\t";
            }

            if (format_string.empty()) {
                std::cout << std::fixed << std::setprecision(decimal_places) << x << "\t" << y;
            } else {
                // Use custom format string (simplified)
                std::cout << std::fixed << std::setprecision(4) << x << "\t" << y;
            }

            if (has_z) {
                std::cout << " " << z;
                if (has_m) {
                    std::cout << " " << m;
                }
            }

            std::cout << std::endl;
        }
    }

    delete proj;
    return 0;
}
