// Projection base class
class Projection {
public:
    virtual ~Projection() = default;
    virtual void project(double& lon, double& lat, double& x, double& y, bool inverse = false) = 0;
};

// Mercator projection
class MercatorProjection : public Projection {
private:
    double scale;
public:
    MercatorProjection(double s = 1.0) : scale(s) {}

    void project(double& lon, double& lat, double& x, double& y, bool inverse = false) override {
        if (!inverse) {
            // Forward projection
            x = scale * lon * M_PI_180 * EARTH_RADIUS;
            y = scale * EARTH_RADIUS * std::log(std::tan(M_PI/4.0 + lat * M_PI_180 / 2.0));
        } else {
            // Inverse projection
            lon = x / (scale * EARTH_RADIUS) * M_180_PI;
            lat = (2.0 * std::atan(std::exp(y / (scale * EARTH_RADIUS))) - M_PI/2.0) * M_180_PI;
        }
    }
};

// Default (identity) projection
class IdentityProjection : public Projection {
public:
    void project(double& lon, double& lat, double& x, double& y, bool inverse = false) override {
        x = lon;
        y = lat;
    }
};

