void transform_mercator(double lon, double lat, double& x, double& y, bool inverse, double scale) {
    if (!inverse) {
        x = scale * lon * M_PI_180 * EARTH_RADIUS;
        y = scale * EARTH_RADIUS * std::log(std::tan(M_PI/4.0 + lat * M_PI_180 / 2.0));
    } else {
        lon = x / (scale * EARTH_RADIUS) * M_180_PI;
        lat = (2.0 * std::atan(std::exp(y / (scale * EARTH_RADIUS))) - M_PI/2.0) * M_180_PI;
    }
}

std::string format_dms(double degrees) {
    bool is_negative = degrees < 0;
    double abs_deg = std::abs(degrees);

    int d = (int)abs_deg;
    double minutes_frac = (abs_deg - d) * 60;
    int m = (int)minutes_frac;
    double s = (minutes_frac - m) * 60;

    std::ostringstream oss;
    oss << d << "d" << m << "'";
    oss << std::fixed << std::setprecision(2) << s << "\"";

    if (is_negative) {
        oss << "S";
    } else {
        oss << "N";
    }

    return oss.str();
}

