            } else {
                x = lon;
                y = lat;
            }

            if (echo_input) {
                std::cout << lon << " " << lat << "\t";
            }

            std::cout << format_number(x, decimal_places) << "\t" << format_number(y, decimal_places);

            if (has_z) {
                std::cout << " ";
                // Output z without forcing precision
                if (z == (int)z) {
                    std::cout << (int)z;
                } else {
                    std::cout << z;
                }
                if (has_m) {
                    std::cout << " ";
                    if (m == (int)m) {
                        std::cout << (int)m;
                    } else {
                        std::cout << m;
                    }
                }
            }

            std::cout << std::endl;
        }
    }

    return 0;
}
