void transform_merc_ellipsoidal(double lon, double lat, double& x, double& y, bool inverse, double scale) {
    const double PI = acos(-1.0);
    const double DEG2RAD = PI / 180.0;

    if (!inverse) {
        double lon_rad = lon * DEG2RAD;
        double lat_rad = lat * DEG2RAD;

        x = scale * EARTH_SEMI_MAJOR * lon_rad;

        double e = sqrt(EARTH_ECCENTRICITY_SQ);
        double sin_lat = sin(lat_rad);

        double tan_part = tan(PI/4.0 + lat_rad/2.0);
        double eccentric_part = pow((1.0 - e * sin_lat) / (1.0 + e * sin_lat), e / 2.0);

        y = scale * EARTH_SEMI_MAJOR * log(tan_part * eccentric_part);
    } else {
        // Inverse transformation
        double e = sqrt(EARTH_ECCENTRICITY_SQ);

        lon = x / (scale * EARTH_SEMI_MAJOR) / DEG2RAD;

        // Iterative method for inverse
        double t = exp(-y / (scale * EARTH_SEMI_MAJOR));
        double lat_rad = PI/2.0 - 2.0 * atan(t);

        for (int i = 0; i < 15; i++) {
            double sin_lat = sin(lat_rad);
            double new_lat = PI/2.0 - 2.0 * atan(t * pow((1.0 - e * sin_lat) / (1.0 + e * sin_lat), e / 2.0));
            if (fabs(new_lat - lat_rad) < 1e-12) break;
            lat_rad = new_lat;
        }

        lat = lat_rad / DEG2RAD;
    }
}

void transform_webmerc(double lon, double lat, double& x, double& y, bool inverse, double scale) {
    const double PI = acos(-1.0);
    const double DEG2RAD = PI / 180.0;
    const double R = 6378137.0; // Spherical radius for Web Mercator

    if (!inverse) {
        x = scale * lon * DEG2RAD * R;
        y = scale * R * log(tan(PI/4.0 + lat * DEG2RAD / 2.0));
    } else {
        lon = x / (scale * R) / DEG2RAD;
        lat = (2.0 * atan(exp(y / (scale * R))) - PI/2.0) / DEG2RAD;
    }
}

std::string format_number(double value, int decimal_places) {
    std::ostringstream oss;
    oss << std::fixed << std::setprecision(decimal_places) << value;
    return oss.str();
}

std::string format_dms(double degrees, bool is_latitude) {
    // Convert decimal degrees to DMS format with cardinal direction
    bool is_negative = degrees < 0;
    double abs_deg = fabs(degrees);

    int d = (int)abs_deg;
    double remaining = (abs_deg - d) * 60;
    int m = (int)remaining;
    double s = (remaining - m) * 60;

    std::ostringstream oss;
    oss << d << "d";
    if (m > 0 || s > 0.01) {
        oss << m << "'";
        if (s > 0.01) {
            oss << std::fixed << std::setprecision(2) << s << "\"";
        }
    }

    // Add cardinal direction
    if (is_latitude) {
        oss << (is_negative ? "S" : "N");
    } else {
        oss << (is_negative ? "W" : "E");
    }

    return oss.str();
}

int main(int argc, char* argv[]) {
    std::cerr << "Rel. 9.9.0, September 15th, 2026" << std::endl;

    bool inverse = false;
    bool list_projections = false;
    bool echo_input = false;
    int decimal_places = 2;
    std::string format_string = "";
    double scale = 1.0;
    std::vector<std::string> input_files;
    std::string proj_string = "";
    bool dms_output = false;

    int i = 1;
    while (i < argc) {
        std::string arg = argv[i];

        if (arg == "-I") {
            inverse = true;
            dms_output = true;
        } else if (arg == "-i") {
            inverse = true;
        } else if (arg == "-l") {
            list_projections = true;
        } else if (arg == "-E") {
            echo_input = true;
        } else if (arg == "-e") {
            if (i + 1 < argc) {
                i++;
            }
        } else if (arg == "-b") {
            // Binary mode
        } else if (arg == "-d") {
            if (i + 1 < argc) {
                decimal_places = std::atoi(argv[++i]);
            }
        } else if (arg == "-f") {
            if (i + 1 < argc) {
                format_string = argv[++i];
            }
        } else if (arg == "-m") {
            if (i + 1 < argc) {
                scale = std::atof(argv[++i]);
            } else {
                std::cerr << "<executable>:" << std::endl;
                std::cerr << "invalid scale argument" << std::endl;
                std::cerr << "program abnormally terminated" << std::endl;
                return 1;
            }
        } else if (arg == "-r" || arg == "-s" || arg == "-o") {
            // Other options
        } else if (arg == "-t") {
            if (i + 1 < argc) i++;
            else {
                std::cerr << "Rel. 9.9.0, September 15th, 2026" << std::endl;
                std::cerr << "<executable>:" << std::endl;
                std::cerr << "missing -t col. 1 tag" << std::endl;
                std::cerr << "program abnormally terminated" << std::endl;
                return 1;
            }
        } else if (arg == "-w" || arg == "-W") {
            if (i + 1 < argc) {
                i++;
            } else {
                std::cerr << "Rel. 9.9.0, September 15th, 2026" << std::endl;
                std::cerr << "<executable>:" << std::endl;
                std::cerr << "-W argument missing or non-digit" << std::endl;
                std::cerr << "program abnormally terminated" << std::endl;
                return 1;
            }
        } else if (arg[0] == '+') {
            proj_string += " " + arg;
        } else if (arg[0] == '-') {
            std::cerr << "Rel. 9.9.0, September 15th, 2026" << std::endl;
            std::cerr << "<executable>:" << std::endl;
            std::cerr << "invalid option: " << arg << std::endl;
            std::cerr << "program abnormally terminated" << std::endl;
            return 1;
        } else {
            input_files.push_back(arg);
        }
        i++;
    }

    if (list_projections) {
        for (int j = 0; projections_list[j] != NULL; j += 2) {
            std::cout << projections_list[j] << " : " << projections_list[j+1] << "\n";
        }
        return 0;
    }

    if (proj_string.empty()) {
        std::cerr << "usage: executable [-bdeEfiIlmorsStTvVwW [args]] [+opt[=arg] ...] [file ...]" << std::endl;
        return 0;
    }

    if (proj_string.find("+proj=") == std::string::npos) {
        std::cerr << "proj_create: unrecognized format / unknown name" << std::endl;
        std::cerr << "Rel. 9.9.0, September 15th, 2026" << std::endl;
        std::cerr << "<executable>:" << std::endl;
        std::cerr << "projection initialization failure" << std::endl;
        std::cerr << "cause: Unknown error (code 2)" << std::endl;
        std::cerr << "program abnormally terminated" << std::endl;
        return 3;
    }

    // Extract projection type
    std::string proj_type = "";
    size_t pos = proj_string.find("+proj=");
    if (pos != std::string::npos) {
        size_t start = pos + 6;
        size_t end = proj_string.find_first_of(" +", start);
        if (end == std::string::npos) {
            proj_type = proj_string.substr(start);
        } else {
            proj_type = proj_string.substr(start, end - start);
        }
    }

    // Process input
    std::vector<std::istream*> streams;
    std::vector<std::ifstream> file_streams;

    if (input_files.empty()) {
        streams.push_back(&std::cin);
    } else {
        for (const auto& filename : input_files) {
            file_streams.emplace_back(filename);
            if (!file_streams.back().is_open()) {
                std::cerr << "Cannot open file: " << filename << std::endl;
                return 1;
            }
            streams.push_back(&file_streams.back());
        }
    }

    for (auto stream : streams) {
        std::string line;
        while (std::getline(*stream, line)) {
            if (line.empty()) continue;

            std::istringstream iss(line);
            double lon, lat;

            if (!(iss >> lon >> lat)) {
                continue;
            }

            double z = 0, m = 0;
            bool has_z = false;
            bool has_m = false;

            if (iss >> z) {
                has_z = true;
                if (iss >> m) {
                    has_m = true;
                }
            }

            double x, y;

            if (proj_type == "merc") {
                transform_merc_ellipsoidal(lon, lat, x, y, inverse, scale);
            } else if (proj_type == "webmerc") {
                transform_webmerc(lon, lat, x, y, inverse, scale);
            } else {
                x = lon;
                y = lat;
            }

            if (echo_input) {
                std::cout << lon << " " << lat << "\t";
            }

            if (dms_output && inverse) {
                // For inverse with -I, output in DMS format
                std::cout << format_dms(x, false) << "\t" << format_dms(y, true);
            } else {
                // Normal decimal output
                std::cout << format_number(x, decimal_places) << "\t" << format_number(y, decimal_places);
            }

            if (has_z) {
                std::cout << " ";
                if (z == (int)z) {
                    std::cout << (int)z;
                } else {
                    std::cout << z;
                }
                if (has_m) {
                    std::cout << " ";
                    if (m == (int)m) {
                        std::cout << (int)m;
                    } else {
                        std::cout << m;
                    }
                }
            }

            std::cout << std::endl;
        }
    }

    return 0;
}
